import{_ as o,a0 as e,w as s,s as a,ao as x,I as t,x as n,a1 as r,A as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const G=JSON.parse('{"title":"4 个最好的 Linux 引导程序 | LCTT x X-CMD","titleTemplate":false,"description":"4 个最好的 Linux 引导程序 | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"4 个最好的 Linux 引导程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"4 个最好的 Linux 引导程序 | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160828  4 Best Linux Boot Loaders","title":"4 个最好的 Linux 引导程序","tag":"201609","desc":""},"relativePath":"201609/20160828  4 Best Linux Boot Loaders.md","filePath":"[post].md"}'),d={name:"201609/20160828  4 Best Linux Boot Loaders.md"};function p(L,l,B,f,T,m){const i=e("Link");return s(),a("div",null,[l[21]||(l[21]=x('<h1 id="_4-个最好的-linux-引导程序" tabindex="-1">4 个最好的 Linux 引导程序 <a class="header-anchor" href="#_4-个最好的-linux-引导程序" aria-label="Permalink to “4 个最好的 Linux 引导程序”">​</a></h1><p>当你打开你的机器，开机自检（POST）成功完成后，BIOS（基本输入输出系统）立即定位所配置的引导介质，并从 MBR（主引导记录）或 GUID（全局唯一标识符）分区表读取一些命令，这是引导介质的最前面 512 个字节内容。主引导记录（MBR）中包含两个重要的信息集合，第一个是引导程序，第二个是分区表。</p><h3 id="什么是引导程序" tabindex="-1">什么是引导程序？ <a class="header-anchor" href="#什么是引导程序" aria-label="Permalink to “什么是引导程序？”">​</a></h3><p>引导程序（Boot Loader）是存储在 MBR（主引导记录）或 GUID（全局唯一标识符）分区表中的一个小程序，用于帮助把操作系统装载到内存中。如果没有引导程序，那么你的操作系统将不能够装载到内存中。</p><p>有一些我们可以随同 Linux 安装到系统上的引导程序，在这篇文章里，我将简要地谈论几个最好的可以与 Linux 一同工作的 Linux 引导程序。</p><h3 id="_1-gnu-grub" tabindex="-1">1. GNU GRUB <a class="header-anchor" href="#_1-gnu-grub" aria-label="Permalink to “1. GNU GRUB”">​</a></h3><p>GNU GRUB 是一个非常受欢迎，也可能是用的最多的具有多重引导能力的 Linux 引导程序，它以原始的 Eirch Stefan Broleyn 发明的 GRUB（GRand Unified Bootlader）为基础。GNU GRUB 增强了原来的 GRUB，带来了一些改进、新的特性和漏洞修复。</p><p>重要的是，GRUB 2 现在已经取代了 GRUB。值得注意的是，GRUB 这个名字被重新命名为 GRUB Legacy，但没有活跃开发，不过，它可以用来引导老的系统，因为漏洞修复依然继续。</p><p>GRUB 具有下面一些显著的特性：</p><ul><li>支持多重引导</li><li>支持多种硬件结构和操作系统，比如 Linux 和 Windows</li><li>提供一个类似 Bash 的交互式命令行界面，从而用户可以运行 GRUB 命令来和配置文件进行交互</li><li>允许访问 GRUB 编辑器</li><li>支持设置加密口令以确保安全</li><li>支持从网络进行引导，以及一些次要的特性</li></ul>',10)),t("p",null,[l[1]||(l[1]=n("访问主页: ",-1)),r(i,{href:"https://www.gnu.org/software/grub/"},{default:u(()=>[...l[0]||(l[0]=[n("https://www.gnu.org/software/grub/",-1)])]),_:1})]),l[22]||(l[22]=t("h3",{id:"_2-lilo-linux-引导程序-linux-loader",tabindex:"-1"},[n("2. LILO（Linux 引导程序（LInux LOader）） "),t("a",{class:"header-anchor",href:"#_2-lilo-linux-引导程序-linux-loader","aria-label":"Permalink to “2. LILO（Linux 引导程序（LInux LOader））”"},"​")],-1)),l[23]||(l[23]=t("p",null,"LILO 是一个简单但强大且非常稳定的 Linux 引导程序。由于 GRUB 有很大改善和增加了许多强大的特性，越来越受欢迎，因此 LILO 在 Linux 用户中已经不是很流行了。",-1)),l[24]||(l[24]=t("p",null,"当 LILO 引导的时候，单词“LILO”会出现在屏幕上，并且每一个字母会在一个特定的事件发生前后出现。然而，从 2015 年 12 月开始，LILO 的开发停止了，它有许多特性比如下面列举的：",-1)),l[25]||(l[25]=t("ul",null,[t("li",null,"不提供交互式命令行界面"),t("li",null,"支持一些错误代码"),t("li",null,"不支持网络引导（LCTT 译注：其变体 ELILO 支持 TFTP/DHCP 引导）"),t("li",null,"所有的文件存储在驱动的最开始 1024 个柱面上"),t("li",null,"面临 BTFS、GTP、RAID 等的限制")],-1)),t("p",null,[l[3]||(l[3]=n("访问主页: ",-1)),r(i,{href:"http://lilo.alioth.debian.org/"},{default:u(()=>[...l[2]||(l[2]=[n("http://lilo.alioth.debian.org/",-1)])]),_:1})]),l[26]||(l[26]=t("h3",{id:"_3-burg-新的引导程序",tabindex:"-1"},[n("3. BURG - 新的引导程序 "),t("a",{class:"header-anchor",href:"#_3-burg-新的引导程序","aria-label":"Permalink to “3. BURG - 新的引导程序”"},"​")],-1)),l[27]||(l[27]=t("p",null,"基于 GRUB，BURG 是一个相对来说比较新的引导程序（LCTT 译注：已于 2011 年停止了开发）。由于 BURG 起源于 GRUB, 所以它带有一些 GRUB 主要特性。尽管如此, BURG 也提供了一些出色的特性，比如一种新的对象格式可以支持包括 Linux、Windows、Mac OS、 FreeBSD 等多种平台。",-1)),l[28]||(l[28]=t("p",null,"另外，BURG 支持可高度配置的文本和图标模式的引导菜单，计划增加的“流”支持未来可以不同的输入/输出设备一同工作。",-1)),t("p",null,[l[5]||(l[5]=n("访问主页: ",-1)),r(i,{href:"https://launchpad.net/burg"},{default:u(()=>[...l[4]||(l[4]=[n("https://launchpad.net/burg",-1)])]),_:1})]),l[29]||(l[29]=t("h3",{id:"_4-syslinux",tabindex:"-1"},[n("4. Syslinux "),t("a",{class:"header-anchor",href:"#_4-syslinux","aria-label":"Permalink to “4. Syslinux”"},"​")],-1)),l[30]||(l[30]=t("p",null,"Syslinux 是一种能从光盘驱动器、网络等进行引导的轻型引导程序。Syslinux 支持诸如 MS-DOS 上的 FAT、 Linux 上的 ext2、ext3、ext4 等文件系统。Syslinux 也支持未压缩的单一设备上的 Btrfs。",-1)),l[31]||(l[31]=t("p",null,"注意由于 Syslinux 仅能访问自己分区上的文件，因此不具备多重文件系统引导能力。",-1)),t("p",null,[l[7]||(l[7]=n("访问主页: ",-1)),r(i,{href:"http://www.syslinux.org/wiki/index.php?title=The_Syslinux_Project"},{default:u(()=>[...l[6]||(l[6]=[n("http://www.syslinux.org/wiki/index.php?title=The_Syslinux_Project",-1)])]),_:1})]),l[32]||(l[32]=t("h3",{id:"结论",tabindex:"-1"},[n("结论 "),t("a",{class:"header-anchor",href:"#结论","aria-label":"Permalink to “结论”"},"​")],-1)),l[33]||(l[33]=t("p",null,"一个引导程序允许你在你的机器上管理多个操作系统，并在某个的时间选择其中一个使用。没有引导程序，你的机器就不能够装载内核以及操作系统的剩余部分。",-1)),l[34]||(l[34]=t("p",null,"我们是否遗漏了任何一流的 Linux 引导程序？如果有请让我们知道，请在下面的评论表中填入值得推荐的 Linux 系统引导程序。",-1)),l[35]||(l[35]=t("hr",null,null,-1)),t("p",null,[l[9]||(l[9]=n("via: ",-1)),r(i,{href:"http://www.tecmint.com/best-linux-boot-loaders/"},{default:u(()=>[...l[8]||(l[8]=[n("http://www.tecmint.com/best-linux-boot-loaders/",-1)])]),_:1})]),t("p",null,[l[13]||(l[13]=n("作者：",-1)),r(i,{href:"http://www.tecmint.com/best-linux-boot-loaders/"},{default:u(()=>[...l[10]||(l[10]=[n("Aaron Kili",-1)])]),_:1}),l[14]||(l[14]=n(" 译者：",-1)),r(i,{href:"https://github.com/ucasFL"},{default:u(()=>[...l[11]||(l[11]=[n("ucasFL",-1)])]),_:1}),l[15]||(l[15]=n(" 校对：",-1)),r(i,{href:"https://github.com/wxy"},{default:u(()=>[...l[12]||(l[12]=[n("wxy",-1)])]),_:1})]),t("p",null,[l[18]||(l[18]=n("本文由 ",-1)),r(i,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...l[16]||(l[16]=[n("LCTT",-1)])]),_:1}),l[19]||(l[19]=n(" 原创编译，",-1)),r(i,{href:"https://linux.cn/"},{default:u(()=>[...l[17]||(l[17]=[n("Linux中国",-1)])]),_:1}),l[20]||(l[20]=n(" 荣誉推出",-1))])])}const U=o(d,[["render",p]]);export{G as __pageData,U as default};
